            btnInventory     .Click += (_,__) => ShowOnce<InventoryDashboard>();
            btnVehicleDashboard.Click+= (_,__) => ShowOnce<VehicleDashboard>();
            btnReporting     .Click += (_,__) => ShowOnce<ReportingDashboard>();
